class ResourceHandle {
    int* dataPtr;
    size_t length;
public:
    ResourceHandle(size_t len) : length(len), dataPtr(new int[len]) {}
    ~ResourceHandle() { delete[] dataPtr; }

    // Copy Constructor: Essential for Deep Copy
    ResourceHandle(const ResourceHandle& source) 
        // 1. Copy simple members
        : length(source.length) 
    {
        // 2. Allocate new memory for resource
        dataPtr = new int[length];

        // 3. Copy contents (Deep Copy)
        for (size_t i = 0; i < length; ++i) {
            dataPtr[i] = source.dataPtr[i];
        }
    }

    // Usage: ResourceHandle b = a;
};
